/**
 * Tiny static image server for the gtp-launch P4 rehearsal (127.0.0.1:54328,
 * local only). Serves the files generated by the fixture seeder and a few
 * hostile paths for the G36 hybrid checks:
 *   /special/redirect-evil.jpg  -> 302 to a host that is NOT allow-listed
 *   /special/big.jpg            -> a 25 MB body (cap test)
 *   /special/lying.jpg          -> content-length 10, body 2 MB (the client must not trust it)
 *   /special/chunked-big.jpg    -> no content-length, 3 MB body (streamed cap)
 *   /special/wrong-magic.jpg    -> text served as image/jpeg
 *   /storage/v1/object/sign/... -> 403 (signed-URL look-alike)
 */
import { createServer } from "node:http";
import { createReadStream, existsSync, statSync } from "node:fs";
import path from "node:path";
import { repoRoot } from "../../lib/out-dir";

const DIR = process.env.GTP_FIXTURE_IMAGES_DIR ?? path.join(repoRoot(), "scripts/migrate/out/fixture-images");
const PORT = Number(process.env.GTP_FIXTURE_IMAGES_PORT ?? 54328);

const server = createServer((req, res) => {
  const url = new URL(req.url ?? "/", "http://127.0.0.1");
  const p = url.pathname;
  if (p === "/special/redirect-evil.jpg") {
    res.writeHead(302, { location: "https://evil.fixture.invalid/x.jpg" });
    return res.end();
  }
  if (p === "/special/big.jpg") {
    const size = 25 * 1024 * 1024;
    res.writeHead(200, { "content-type": "image/jpeg", "content-length": String(size) });
    const chunk = Buffer.alloc(1024 * 1024, 0xff);
    let sent = 0;
    const pump = () => {
      while (sent < size) {
        sent += chunk.length;
        if (!res.write(chunk)) return res.once("drain", pump);
      }
      res.end();
    };
    return pump();
  }
  if (p === "/special/lying.jpg") {
    res.writeHead(200, { "content-type": "image/jpeg", "content-length": "10" });
    // body larger than declared; the client must stop at its cap
    res.socket?.write(Buffer.alloc(0));
    return res.end(Buffer.alloc(2 * 1024 * 1024, 0xff));
  }
  if (p === "/special/chunked-big.jpg") {
    // no content-length at all: only the client's streamed byte cap can stop it
    res.writeHead(200, { "content-type": "image/jpeg" });
    res.write(Buffer.from([0xff, 0xd8, 0xff, 0xe0]));
    return res.end(Buffer.alloc(3 * 1024 * 1024, 0xff));
  }
  if (p.startsWith("/storage/v1/object/sign/")) {
    res.writeHead(403);
    return res.end();
  }
  const file = path.join(DIR, path.normalize(p).replace(/^(\.\.[/\\])+/, ""));
  if (!file.startsWith(DIR) || !existsSync(file) || !statSync(file).isFile()) {
    res.writeHead(404);
    return res.end();
  }
  res.writeHead(200, { "content-type": "image/jpeg", "content-length": String(statSync(file).size) });
  createReadStream(file).pipe(res);
});
server.listen(PORT, "127.0.0.1", () => console.log(`[fixture-images] serving ${DIR} on http://127.0.0.1:${PORT}`));
